from math import comb

def calculate_min_monochromatic(n):
    min_sum = float('inf')

    # Iterate through all partitions (r, b) such that r + b = n and r <= b
    for r in range(n // 2 + 1):
        b = n - r
        # Calculate the sum of monochromatic triangles
        try:
            current_sum = comb(r, 3) + comb(b, 3)
        except ValueError:
            # comb(k, 3) is 0 if k < 3
            current_sum = 0

        if current_sum < min_sum:
            min_sum = current_sum

    return min_sum

results = {}
for n in range(1, 7):
    results[n] = calculate_min_monochromatic(n)

print(results)

